import { NextResponse } from "next/server";
import { z } from "zod";
import { withActor } from "@/server/db/context";
import { DomainError } from "@/server/errors";
import { actorRoute } from "@/server/http";

/** Redirects to the authorized download of the generated report PDF (generated by the worker). */
export const GET = actorRoute({ params: z.object({ id: z.uuid() }) }, async ({ actor, params, request }) => {
  const doc = await withActor(actor, async (tx) => {
    const report = await tx.serviceReport.findUnique({ where: { id: params.id }, select: { id: true } });
    if (!report) throw new DomainError("NOT_FOUND", "Rapport introuvable.");
    return tx.document.findFirst({ where: { reportId: report.id, kind: "REPORT_PDF", status: "READY" }, select: { id: true } });
  });
  if (!doc) throw new DomainError("NOT_FOUND", "Le PDF du rapport est en cours de génération. Réessayez dans quelques instants.");
  return NextResponse.redirect(new URL(`/api/v1/documents/${doc.id}/download`, request.url), 303);
});
